def prefix(grid):
    H, W = len(grid), len(grid[0])
    P = [[0] * (W + 1) for _ in range(H + 1)]
    for r in range(H):
        row = grid[r]
        for c in range(W):
            P[r + 1][c + 1] = P[r][c + 1] + P[r + 1][c] - P[r][c] + (0 if row[c] == 0 else 1)
    return P


def candidates(grid, strict):
    """All all-zero rectangles whose 1-cell surrounding frame is all zeros.
    strict=True: the frame must lie fully inside the grid.
    strict=False: frame clipped at grid borders is allowed."""
    H, W = len(grid), len(grid[0])
    P = prefix(grid)

    def nz(r1, c1, r2, c2):
        r1 = max(r1, 0); c1 = max(c1, 0); r2 = min(r2, H - 1); c2 = min(c2, W - 1)
        if r1 > r2 or c1 > c2:
            return 0
        return P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1]

    res = []
    r1lo, r2hi = (1, H - 2) if strict else (0, H - 1)
    c1lo, c2hi = (1, W - 2) if strict else (0, W - 1)
    for r1 in range(r1lo, r2hi + 1):
        for r2 in range(r1, r2hi + 1):
            for c1 in range(c1lo, c2hi + 1):
                for c2 in range(c1, c2hi + 1):
                    fr1, fr2, fc1, fc2 = r1 - 1, r2 + 1, c1 - 1, c2 + 1
                    got = nz(fr1, fc1, fr2, fc2)
                    # frame region must contain zero non-zero cells
                    if got == 0:
                        res.append(((r2 - r1 + 1) * (c2 - c1 + 1), r1, c1, r2, c2))
    res.sort(key=lambda t: -t[0])
    return res


def fill(grid, rect):
    g = [row[:] for row in grid]
    _, r1, c1, r2, c2 = rect
    for r in range(r1, r2 + 1):
        for c in range(c1, c2 + 1):
            g[r][c] = 8
    return g


for name, inp, outp in [("ex1", ex1_in, ex1_out), ("ex2", ex2_in, ex2_out), ("ex3", ex3_in, ex3_out)]:
    for strict in (True, False):
        cands = candidates(inp, strict)
        best = cands[0]
        pred = fill(inp, best)
        print(name, "strict" if strict else "lenient", "best:", best,
              "match:", pred == outp, "top4:", cands[:4])

